referenceSolutions.javascript:
export function solve(events, wait, horizon) {
  const out = [];
  let last = -Infinity;
  for (const e of events) {
    if (e.time - last >= wait) {
      out.push({ time: e.time, value: e.value });
      last = e.time;
    }
  }
  return out;
}

