export function solve(
  events: { time: number; kind: string; value?: any }[],
  wait: number,
  horizon: number,
): any {
  const out: any[] = [];
  let last = -Infinity;
  for (const e of events) {
    if (e.time - last >= wait) {
      out.push({ time: e.time, value: e.value });
      last = e.time;
    }
  }
  return out;
}
